theme.css:
/* theme: Morning in the Interim | The day's news — hot inflation, hopeful history, and a tech giant's debut — moves in many directions at once, and this page catches that momentum without forcing a single mood. */
/* mood: neutral */
/* layout: hero=split; major-events=lede/stack; political-news=numbered/grid-2; financial-news=stat/masonry; tech-news=outline/grid-3; entertainment-news=tile/grid-2; sports=split/masonry; music-releases=plain/stack; stock-analysis=stat/grid-2; outlook=timeline/stack */

.diary-page {
  --paper: #f2f2f0;
  --paper-alt: #e6e6e3;
  --ink: #0d0d0c;
  --ink-soft: #262624;
  --muted: #4f4f4c;
  --accent: #3a3a37;
  --accent-ink: #ffffff;
  --rule: #c9c9c4;
  --font-display: var(--ff-instrument), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
}

/* Hero: a quiet, measured split that lets the day's many currents sit side by side */
.diary-page[data-hero="split"] .diary-hero {
  background:
    linear-gradient(180deg, transparent 0%, var(--paper-alt) 100%),
    var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page[data-hero="split"] .diary-hero-inner {
  padding-block: 2.5rem 3.5rem;
}

.diary-page[data-hero="split"] .diary-kicker {
  margin-top: 1.5rem;
  letter-spacing: 0.22em;
  font-weight: 500;
}

.diary-page[data-hero="split"] .diary-title {
  font-size: clamp(2.75rem, 6vw, 5rem);
  font-weight: 400;
  letter-spacing: 0;
  line-height: 1.1;
  max-width: 22ch;
  color: var(--ink);
}

.diary-page[data-hero="split"] .diary-summary {
  font-size: clamp(1.1rem, 1.8vw, 1.35rem);
  line-height: 1.7;
  max-width: 38rem;
  margin-top: 1rem;
}

.diary-page[data-hero="split"] .diary-theme-note {
  margin-top: 1.5rem;
  font-size: 0.8rem;
}

.diary-page[data-hero="split"] .diary-theme-name {
  background: var(--ink);
  color: var(--paper);
  padding: 0.2rem 0.8rem;
  border-radius: 0;
  font-weight: 500;
}

/* Contents: a lean, linear rail with hairline rules */
.diary-page .diary-toc {
  background: rgba(242, 242, 240, 0.92);
  backdrop-filter: blur(8px);
  border-bottom-color: var(--ink);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  color: var(--muted);
}

.diary-page .diary-toc-link.is-active {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }
  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--ink);
  }
}

/* Sections: generous air, thin rules, a measured pulse */
.diary-page .diary-section {
  padding-block: 3.5rem;
  border-top-color: var(--rule);
}

.diary-page .diary-section-head {
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-size: 0.72rem;
  letter-spacing: 0.25em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-size: clamp(2rem, 4vw, 2.75rem);
  font-weight: 400;
  letter-spacing: 0;
  color: var(--ink);
}

/* A small overdrawn rule under each section title, like a ledger line */
.diary-page .diary-section-title::after {
  content: "";
  display: block;
  width: 3rem;
  height: 2px;
  margin-top: 0.6rem;
  background: var(--ink);
}

/* Major Events: the day's headlines as a considered ledger, each story a standfirst */
.diary-page [data-section="major-events"] .diary-card--lede .diary-card-inner {
  position: relative;
  padding: 1.85rem 0 1.85rem 5.5rem;
  border-top: 1px solid var(--rule);
}

.diary-page [data-section="major-events"] .diary-card--lede .diary-card-inner::before {
  content: "";
  position: absolute;
  left: 0;
  top: 1.8rem;
  width: 3rem;
  height: 1px;
  background: var(--accent);
}

.diary-page [data-section="major-events"] .diary-card--lede .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.9rem;
  font-weight: 400;
  line-height: 1.2;
  margin-bottom: 0.4rem;
  max-width: 38ch;
}

.diary-page [data-section="major-events"] .diary-card--lede .diary-card-bodied {
  margin-top: 0.5rem;
}

.diary-page [data-section="major-events"] .diary-card--lede .diary-card-body {
  font-size: 1.12rem;
  line-height: 1.7;
}

/* Political News: voices and verdicts indexed, two columns of numbered notes */
.diary-page [data-section="political-news"] .diary-card--numbered .diary-card-inner {
  grid-template-columns: 2.5rem minmax(0, 1fr);
  column-gap: 1rem;
  row-gap: 0.5rem;
  padding: 1.25rem 1.25rem 1.25rem 0;
  border-top: 1px solid var(--rule);
}

.diary-page [data-section="political-news"] .diary-card--numbered .diary-card-index {
  font-size: 2rem;
  font-weight: 400;
  color: var(--accent);
}

.diary-page [data-section="political-news"] .diary-card--numbered .diary-card-title {
  font-size: 1.3rem;
  font-weight: 500;
}

.diary-page [data-section="political-news"] .diary-card--numbered .diary-card-body {
  font-size: 1rem;
  line-height: 1.65;
}

/* Financial News: figures demand scale and the dust of a hot number settles on a freeform masonry */
.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-inner {
  padding: 1.5rem 1.25rem 1.25rem;
  border-top: 4px solid var(--ink);
  background: var(--paper);
}

.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-figure {
  font-family: var(--font-ui);
  font-size: 2.5rem;
  font-weight: 600;
  letter-spacing: -0.03em;
  color: var(--ink);
  line-height: 1;
}

.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-title {
  margin-top: 0.5rem;
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 500;
  line-height: 1.15;
}

.diary-page [data-section="financial-news"] .diary-card--stat .diary-card-body {
  font-size: 0.98rem;
  line-height: 1.6;
  margin-top: 0.6rem;
}

/* Tech News: cold hardware facts in neat boxes, no gloss */
.diary-page [data-section="tech-news"] .diary-card--outline .diary-card-inner {
  padding: 1.4rem;
  border: 1px solid var(--rule);
  border-radius: 0;
  background: var(--paper);
}

.diary-page [data-section="tech-news"] .diary-card--outline .diary-card-title {
  font-family: var(--font-ui);
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 0;
  line-height: 1.4;
}

.diary-page [data-section="tech-news"] .diary-card--outline .diary-card-body {
  font-size: 0.97rem;
  line-height: 1.6;
  margin-top: 0.4rem;
}

/* Entertainment: one loud, dark tile for a day of gossip to sit in */
.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-inner {
  padding: 2rem;
  background: var(--ink);
  border-radius: 0;
}

.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 400;
  line-height: 1.2;
  color: var(--paper);
}

.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-body {
  color: var(--paper-alt);
  font-size: 1.02rem;
  line-height: 1.65;
}

.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-body a {
  color: var(--paper);
  border-bottom-color: var(--paper);
}

.diary-page [data-section="entertainment-news"] .diary-card--tile .diary-card-body a:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

/* Sports: scores argue across two columns, separated by a firm vertical rule */
.diary-page [data-section="sports"] .diary-card--split .diary-card-inner {
  padding-top: 1rem;
  border-top: 2px solid var(--ink);
}

@media (min-width: 34rem) {
  .diary-page [data-section="sports"] .diary-card--split .diary-card-inner {
    grid-template-columns: minmax(9rem, 35%) minmax(0, 1fr);
    column-gap: 1.5rem;
  }
}

.diary-page [data-section="sports"] .diary-card--split .diary-card-title {
  font-family: var(--font-ui);
  font-size: 1.1rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--ink);
}

.diary-page [data-section="sports"] .diary-card--split .diary-card-body {
  font-size: 1rem;
  line-height: 1.6;
}

/* Stock Analysis: the day's trades in tight, tabular panels */
.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  padding: 1.25rem 1rem 1rem;
  border-top: 3px solid var(--accent);
}

.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-figure {
  font-family: var(--font-ui);
  font-size: 2rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-title {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: 0.3rem;
}

.diary-page [data-section="stock-analysis"] .diary-card--stat .diary-card-body {
  font-size: 0.92rem;
  line-height: 1.55;
  margin-top: 0.4rem;
}

/* Outlook: a watchful timeline with little dots for what is coming */
.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
}

.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-inner::before {
  left: 0.4rem;
  width: 1px;
  background: var(--rule);
}

.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-inner::after {
  left: 0;
  width: 0.9rem;
  height: 0.9rem;
  top: 0.5rem;
  background: var(--paper);
  border: 2px solid var(--ink);
  box-shadow: none;
  border-radius: 50%;
}

.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 500;
  line-height: 1.3;
  margin-bottom: 0.25rem;
}

.diary-page [data-section="outlook"] .diary-card--timeline .diary-card-body {
  font-size: 1rem;
  line-height: 1.65;
}

/* Music: players stand alone, our page lets them breathe and the text falls in line */
.diary-page [data-section="music-releases"] .diary-card--plain {
  border-top: 1px solid var(--rule);
  padding-top: 1.5rem;
}

.diary-page [data-section="music-releases"] .diary-card--plain:first-child {
  border-top: 0;
  padding-top: 0;
}

.diary-page [data-section="music-releases"] .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 400;
  line-height: 1.25;
}

.diary-page [data-section="music-releases"] .diary-card-body {
  font-size: 1.06rem;
}

/* Markets block: a quiet row of sparklines that behaves like a ledger at the end of the day */
.diary-page .diary-markets {
  gap: 0.75rem;
}

.diary-page .diary-spark {
  padding: 0.85rem 0.9rem 0.65rem;
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
}

.diary-page .diary-spark-label {
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.diary-page .diary-spark-value {
  font-weight: 600;
}

.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

/* Body prose: even, calm, readable */
.diary-page .diary-prose {
  font-size: 1.08rem;
  line-height: 1.72;
  color: var(--ink-soft);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose a {
  color: var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
  width: 0.5rem;
  height: 1px;
  top: 0.8em;
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

/* Citation links: keep them hanging nicely in a day of many sources */
.diary-page .diary-prose a {
  white-space: normal !important;
  overflow-wrap: anywhere;
  border-bottom: 1px solid currentColor;
  text-decoration: none;
}

/* Give the fine print of the footer a little of the day's calm */
.diary-page .diary-footer {
  border-top-color: var(--rule);
  font-size: 0.8rem;
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* A quiet fade-in for the whole page, nothing repetitive */
@media (prefers-reduced-motion: no-preference) {
  .diary-page {
    animation: diary-fade 480ms ease-out both;
  }

  @keyframes diary-fade {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
}
